@import "tailwindcss";
@import "tw-animate-css";

/*
 * Design tokens for "Carhop Marquee / Gulf Channel", see design-system.md.
 * One theme, dark-base, no light/dark toggle (site-wide page-theme-lock rule).
 */
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 4px;

  /* the five named design-system.md colors */
  --color-bay-dusk: #0e3a3e;
  --color-channel-ink: #082226;
  --color-marquee-amber: #e8a23c;
  --color-seafoam: #ecefe6;
  --color-buoy-red: #d1452b;

  --font-display: var(--font-display-slab), ui-serif, serif;
  --font-body: var(--font-body-archivo), ui-sans-serif, sans-serif;
  --font-mono: var(--font-mono-plex), ui-monospace, monospace;
}

:root {
  --background: #0e3a3e;
  --foreground: #ecefe6;
  --primary: #e8a23c;
  --primary-foreground: #082226;
  --secondary: #082226;
  --secondary-foreground: #ecefe6;
  --muted: #0b2f33;
  --muted-foreground: rgba(236, 239, 230, 0.65);
  --accent: #0b2f33;
  --accent-foreground: #ecefe6;
  --destructive: #d1452b;
  --border: rgba(236, 239, 230, 0.15);
  --input: rgba(236, 239, 230, 0.15);
  --ring: #e8a23c;
  --radius: 0.375rem;
}

@layer base {
  html {
    scroll-behavior: smooth;
  }
  body {
    @apply bg-background text-foreground font-body antialiased;
  }
}

