"use client";

import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";

const WORD = "THE TEXAN DRIVE-IN";
const SESSION_KEY = "texan-marquee-flicker-played";

const SIZE_CLASSES = {
  hero: "text-2xl sm:text-3xl md:text-5xl gap-[3px] md:gap-1",
  nav: "text-[10px] sm:text-xs gap-[2px]",
  footer: "text-sm md:text-base gap-[2px]",
} as const;

/**
 * The site's signature component: "THE TEXAN DRIVE-IN" as individually
 * backlit marquee letter tiles. Only the hero instance flickers on, and
 * only once per browser session (see design-system.md "Motion notes").
 */
export function MarqueeWordmark({
  size = "nav",
  animate = false,
}: {
  size?: keyof typeof SIZE_CLASSES;
  animate?: boolean;
}) {
  const reduceMotion = useReducedMotion();
  const [ready, setReady] = useState(false);
  const [alreadyPlayed, setAlreadyPlayed] = useState(true);

  useEffect(() => {
    if (!animate) return;
    const played = sessionStorage.getItem(SESSION_KEY);
    setAlreadyPlayed(Boolean(played));
    sessionStorage.setItem(SESSION_KEY, "1");
    setReady(true);
  }, [animate]);

  const shouldFlicker = animate && ready && !alreadyPlayed && !reduceMotion;

  return (
    <div
      role="img"
      aria-label="The Texan Drive-In"
      className={`flex flex-wrap items-center font-display font-black leading-none tracking-[-0.01em] ${SIZE_CLASSES[size]}`}
    >
      {WORD.split("").map((char, i) =>
        char === " " ? (
          <span key={i} className="w-1.5 md:w-2" aria-hidden />
        ) : (
          <motion.span
            key={i}
            aria-hidden
            className="inline-flex items-center justify-center rounded-sm bg-channel-ink px-[3px] text-marquee-amber md:px-1"
            style={{ textShadow: "0 0 8px var(--color-marquee-amber)" }}
            initial={shouldFlicker ? { opacity: 0.15 } : { opacity: 1 }}
            animate={
              shouldFlicker
                ? { opacity: [0.15, 1, 0.25, 1, 0.35, 1] }
                : { opacity: 1 }
            }
            transition={
              shouldFlicker
                ? {
                    duration: 0.6,
                    delay: i * 0.015,
                    times: [0, 0.2, 0.4, 0.6, 0.8, 1],
                  }
                : { duration: 0 }
            }
          >
            {char === "-" ? "‑" : char}
          </motion.span>
        ),
      )}
    </div>
  );
}

