import Link from "next/link";
import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";
import { buttonVariants } from "./ui/button";

/**
 * A next/link styled with the shared shadcn button variants, always merged
 * through cn()/tailwind-merge so override classes (pill radius, brand
 * colors per design-system.md) reliably win over the variant defaults.
 */
export function CtaLink({
  className,
  variant,
  href,
  ...props
}: ComponentProps<typeof Link> &
  Pick<Parameters<typeof buttonVariants>[0], "variant">) {
  return (
    <Link
      href={href}
      className={cn(buttonVariants({ variant }), className)}
      {...props}
    />
  );
}

