import type { ScheduleRow } from "@/lib/schedule";

/**
 * The site's signature schedule component: a physical letter-board look.
 * Reused as a small teaser on the homepage and full-size on /whats-on
 * (see design-system.md and page-plans/home.md + whats-on.md).
 */
export function MarqueeBoard({
  rows,
  variant = "full",
}: {
  rows: ScheduleRow[];
  variant?: "teaser" | "full";
}) {
  const display = variant === "teaser" ? rows.slice(0, 1) : rows;

  return (
    <div className="divide-y divide-border rounded-sm border border-border bg-channel-ink">
      {display.map((row) => (
        <div
          key={row.day}
          className="flex flex-col gap-1 px-4 py-3 sm:flex-row sm:items-center sm:justify-between md:px-6 md:py-4"
        >
          <span className="shrink-0 font-mono text-xs tracking-[0.08em] text-seafoam/60 uppercase">
            {row.day}
          </span>
          <span
            className={
              row.pending
                ? "font-body text-sm text-seafoam/50 italic sm:text-right"
                : "font-display text-base font-bold text-marquee-amber sm:text-right sm:text-xl"
            }
          >
            {row.act}
          </span>
        </div>
      ))}
    </div>
  );
}

