import Image from "next/image";

const GAMES = [
  {
    src: "/images/pool-table.jpg",
    alt: "Close-up of a pool table under a hanging bar light",
    label: "Pool Tables",
    big: true,
  },
  {
    src: "/images/darts.jpg",
    alt: "Dartboard mounted on a wood-paneled bar wall",
    label: "Darts",
  },
  {
    src: "/images/shuffleboard.jpg",
    alt: "Shuffleboard table with worn wood grain",
    label: "Shuffleboard",
  },
] as const;

/** Three-item bento grid: one large cell + two stacked, per page-plans/the-bar.md. */
export function AssetGrid() {
  const [big, ...rest] = GAMES;
  return (
    <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
      <Cell item={big} className="md:row-span-2" sizes="(min-width: 768px) 50vw, 100vw" />
      {rest.map((item) => (
        <Cell key={item.label} item={item} sizes="(min-width: 768px) 25vw, 100vw" />
      ))}
    </div>
  );
}

function Cell({
  item,
  className = "",
  sizes,
}: {
  item: (typeof GAMES)[number];
  className?: string;
  sizes: string;
}) {
  return (
    <figure className={`relative aspect-[4/3] overflow-hidden rounded-sm ${className}`}>
      <Image src={item.src} alt={item.alt} fill sizes={sizes} className="object-cover" />
      <figcaption className="absolute bottom-0 left-0 bg-channel-ink/85 px-3 py-1.5 font-mono text-xs tracking-[0.08em] text-seafoam uppercase">
        {item.label}
      </figcaption>
    </figure>
  );
}

