import { YELP_URL } from "@/lib/contact";

/**
 * No owner-approved atmosphere quote is licensed for use yet (see
 * assets.md): no fabricated quote ships under any circumstance, so this
 * renders an honest fallback that points to the real reviews instead of
 * inventing an attributed line.
 */
export function PullQuote({ quote, attribution }: { quote?: string; attribution?: string }) {
  return (
    <section className="mx-auto max-w-6xl px-4 py-16 md:px-8 md:py-24">
      <h2 className="text-3xl leading-tight font-bold tracking-tight text-seafoam md:text-4xl">
        A Room That Gets Used.
      </h2>
      {quote ? (
        <blockquote className="mt-6 max-w-[65ch] border-l-4 border-marquee-amber pl-6">
          <p className="font-display text-xl text-seafoam md:text-2xl">
            &ldquo;{quote}&rdquo;
          </p>
          {attribution && (
            <cite className="mt-3 block font-mono text-xs text-seafoam/60 not-italic uppercase">
              {attribution}
            </cite>
          )}
        </blockquote>
      ) : (
        <p className="mt-6 max-w-[65ch] font-body text-base text-seafoam/80 md:text-lg">
          Real reviews live on Yelp and Google, not staged testimonials here.
