import { MapPin } from "@phosphor-icons/react/dist/ssr";
import { CtaLink } from "./CtaLink";
import { MAP_QUERY, YELP_URL } from "@/lib/contact";

/**
 * No confirmed street address exists (brief.md), so this embeds a Google
 * Maps search by business name + city only, never a fabricated address.
 * Buoy Red is used once here (the map-pin glyph), its one approved
 * decorative use per design-system.md.
 */
export function MapEmbed() {
  const query = encodeURIComponent(MAP_QUERY);

  return (
    <div id="map" className="scroll-mt-20">
      <div className="relative aspect-[4/3] w-full overflow-hidden rounded-sm border border-border md:aspect-[16/9]">
        <iframe
          title="Map showing The Texan Drive-In in Corpus Christi, TX"
          src={`https://www.google.com/maps?q=${query}&output=embed`}
          className="absolute inset-0 h-full w-full border-0"
          loading="lazy"
          referrerPolicy="no-referrer-when-downgrade"
        />
      </div>
      <div className="mt-4 flex flex-wrap items-center gap-4">
        <MapPin weight="fill" size={22} className="text-buoy-red" aria-hidden />
        <CtaLink
          href={`https://www.google.com/maps/search/?api=1&query=${query}`}
          target="_blank"
          rel="noopener noreferrer"
          className="h-11 rounded-full bg-marquee-amber px-5 text-sm text-channel-ink hover:bg-marquee-amber/90"
        >
          Open in Google Maps
        </CtaLink>
      </div>
      <p className="mt-3 font-mono text-xs tracking-[0.05em] text-seafoam/50">
        No confirmed street address yet — see the{" "}
        <a
          href={YELP_URL}
          target="_blank"
          rel="noopener noreferrer"
          className="underline hover:text-marquee-amber"
        >
          Yelp listing
        </a>{" "}
        for exact directions.
      </p>
    </div>
  );
}

