import type { Metadata } from "next";
import { Archivo, IBM_Plex_Mono, Roboto_Slab } from "next/font/google";
import "./globals.css";
import { NavBar } from "@/components/NavBar";
import { Footer } from "@/components/Footer";

const displayFont = Roboto_Slab({
  subsets: ["latin"],
  weight: ["700", "900"],
  variable: "--font-display-slab",
  display: "swap",
});

const bodyFont = Archivo({
  subsets: ["latin"],
  weight: ["400", "500"],
  variable: "--font-body-archivo",
  display: "swap",
});

const monoFont = IBM_Plex_Mono({
  subsets: ["latin"],
  weight: ["400", "500"],
  variable: "--font-mono-plex",
  display: "swap",
});

export const metadata: Metadata = {
  title: "The Texan Drive-In | Corpus Christi Neighborhood Bar",
  description:
    "Pool, darts, shuffleboard, a patio, and live bands on weekends. Rated 4.3 stars by more than 500 regulars on Google.",
  openGraph: {
    title: "The Texan Drive-In",
    description:
      "Pool, darts, shuffleboard, a patio, and live bands on weekends in Corpus Christi, TX.",
    images: ["/images/og-bg.jpg"],
  },
};

// Exact JSON-LD block from implementation.md, plus a `telephone` key: the
// only contact fact this loop is authorized to publish as real, sourced
// data (not a placeholder). No `address` object and no `email` key, since
// neither fact is confirmed.
const jsonLd = {
  "@context": "https://schema.org",
  "@type": "BarOrPub",
  name: "The Texan Drive-In",
  telephone: "+13614445522",
  addressLocality: "Corpus Christi",
  addressRegion: "TX",
  addressCountry: "US",
  aggregateRating: {
    "@type": "AggregateRating",
    ratingValue: "4.3",
    reviewCount: "510",
  },
  sameAs: [
    "https://www.facebook.com/Thetexancorpuschristi/",
    "https://www.yelp.com/biz/the-texan-drive-in-corpus-christi",
  ],
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={`${displayFont.variable} ${bodyFont.variable} ${monoFont.variable} h-full`}
    >
      <body className="flex min-h-full flex-col">
        <script
          type="application/ld+json"
          // eslint-disable-next-line react/no-danger
          dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
        />
        <NavBar />
        <main className="flex-1">{children}</main>
        <Footer />
      </body>
    </html>
  );
}

